// Normalize webhook body -> publish context. NO repo wipe.
const body = $input.first().json.body || $input.first().json || {};
let appId = String(body.app_id || body.appId || '').toLowerCase();
// Cron / empty body: pick pending Docvat Play ticket if present (never default
// to IMPERIUM - that would upload the wrong package).
if (!appId) {
  try {
    const fs = require('fs');
    if (fs.existsSync('/tmp/codice-ci-pending-docvat-play.json')) {
      const p = JSON.parse(fs.readFileSync('/tmp/codice-ci-pending-docvat-play.json', 'utf8'));
      appId = String(p.app_id || 'docvat').toLowerCase();
    }
  } catch (e) { /* ignore */ }
}
if (!appId) appId = 'imperium';
const packageName = body.package_name || body.packageName || (
  appId === 'docvat' ? 'com.docvat' :
  appId === 'imperium' ? 'com.codiceprogressio.imperiumsic' :
  body.package_name
);
if (!packageName) throw new Error('package_name required');
const track = body.track || 'closed';
const status = body.status || (appId === 'docvat' ? 'completed' : 'draft');
const dryRun = body.dry_run === true || body.dry_run === '1' || body.dryRun === true;
const aabPath = body.aab_path || body.aabPath || (
  appId === 'docvat'
    ? '/work/docvat/dist/documentos-vaticanos-release.aab'
    : '/work/artifacts/imperium-sic-release.aab'
);
const saPath = body.sa_path || body.saPath || '/secrets/play-service-account.json';
return [{
  json: {
    app_id: appId,
    package_name: packageName,
    track,
    status,
    dry_run: dryRun ? '1' : '0',
    aab_path: aabPath,
    sa_path: saPath,
    message: 'PLAY-publish ' + appId + ' ' + packageName,
  }
}];

const raw = String($input.first().json.stdout || '').trim();
let result;
try { result = JSON.parse(raw); } catch (e) {
  throw new Error('Cola acquire invalid JSON: ' + raw.slice(0, 200));
}
const prev = $('Normalize payload').first().json;
const action = result.build_action === 'run' ? 'publish' : result.build_action;
return [{ json: { ...prev, ...result, build_action: action, should_publish: action === 'publish', queue_summary: result.queue_summary || '' } }];

const raw = String($input.first().json.stdout || '').trim();
let result;
try { result = JSON.parse(raw); } catch (e) {
  return [{ json: { build_action: 'done', nudge_other: false, raw: raw.slice(0,200) } }];
}
result.nudge_other = result.nudge_other === true || result.nudge_other === 'true';
return [{ json: result }];
